   "sez": "economia",
   "titolo": "Orsini: tagliare il bilancio europeo è una scelta miope",
   "orig": "Orsini: “Miope tagliare il bilancio europeo. Tetto al gas? A 40 euro avrebbe fatto la differenza”",
   "lead": "Il presidente di Confindustria Orsini ha criticato l'ipotesi di tagliare il bilancio europeo, definendola una decisione miope per la competitività industriale, e ha chiesto l'emissione di debito comune europeo a sostegno delle imprese. Ha inoltre sottolineato che un tetto al prezzo del gas fissato a 40 euro avrebbe fatto la differenza per i costi energetici. Ha infine bollato come «una follia» il sistema ETS, chiedendo che tutte le risorse raccolte vengano restituite alle aziende. Lo riferisce la Repubblica.",
   "more": [
    "Il sistema ETS (Emissions Trading System) è il mercato europeo delle quote di emissione di CO2, strumento chiave della politica climatica dell'UE ma spesso criticato dalle imprese per i costi aggiuntivi imposti alla produzione industriale europea."
   ],
