   "sez": "organizzazioni",
   "titolo": "L'ONU denuncia una 'guerra contro la natura' sulla biodiversità",
   "orig": "The world is waging a ‘war on nature’ as progress on biodiversity targets lags",
   "lead": "Un nuovo rapporto delle Nazioni Unite segnala che meno della metà degli obiettivi nazionali fissati per proteggere piante, animali ed ecosistemi è sulla buona strada. L'allarme arriva pochi giorni prima dell'apertura della conferenza COP17 sulla biodiversità a Yerevan, in Armenia, dove i paesi si riuniranno per discutere i progressi verso gli impegni globali. Lo riferisce UN News.",
   "more": [
    "La COP17 sulla biodiversità segue il quadro globale adottato a Montreal nel 2022, che fissa 23 obiettivi da raggiungere entro il 2030 per arrestare la perdita di biodiversità; i rapporti periodici denunciano ritardi diffusi nell'attuazione da parte dei governi."
   ],
