   "lead": "Il film d'animazione giapponese 'We Are Aliens', diretto da Kōhei Kadowaki, ha vinto il premio Anima't al Sitges Film Festival in Catalogna, Spagna. Kadowaki diventa così il più giovane regista giapponese ad aver ricevuto questo riconoscimento al festival. Lo riferisce Anime News Network, con conferma da Crunchyroll News.",
