   "titolo": "Dal letto d'ospedale, il Papa chiede a Putin una tregua umanitaria a Oleshky",
   "orig": "Pope urges humanitarian ceasefire in Oleshky in call with Russian President",
   "lead": "Papa Leone XIV ha telefonato al presidente russo Vladimir Putin esprimendo «profonda preoccupazione» per la grave situazione umanitaria nella città di Oleshky, nella regione di Kherson, e chiedendo una tregua per consentire l'arrivo di aiuti umanitari. La chiamata è avvenuta mentre il pontefice si trovava ancora in convalescenza dopo l'intervento chirurgico al polmone. Nella città, secondo quanto riferito, le consegne di cibo sono bloccate da maggio. Lo riferiscono Vatican News e Fox News.",
   "more": [
    "Oleshky, nella regione ucraina di Kherson sotto controllo russo, è teatro di gravi difficoltà di accesso umanitario da mesi; gli appelli papali per tregue locali si sono moltiplicati nel corso del conflitto, finora senza esiti concreti sul terreno."
   ],
