   "titolo": "I Brewers attendono l'avversaria per la Serie Mondiale",
   "orig": "¿Guardianes o Rays? El dilema de los Cerveceros para la Serie Mundial",
   "lead": "I Milwaukee Brewers, dopo aver eliminato i Los Angeles Dodgers e conquistato la finale della National League, attendono ora di conoscere l'avversaria nella Serie Mondiale di baseball: la sfida tra Cleveland Guardians e Tampa Bay Rays deciderà chi affronterà i Cerveceros, che tornano a giocarsi il titolo per la prima volta dal 1982. La squadra, con un budget tra i più contenuti della lega, punta a coronare un percorso costruito con oculatezza. Lo riferisce El Nacional.",
   "more": [
    "La Serie Mondiale è l'atto finale del campionato di baseball nordamericano MLB, che mette di fronte le vincitrici delle due leghe, National e American League, in una serie al meglio delle sette partite."
   ],
