   "id": "z2637e40f",
   "sez": "economia",
   "titolo": "L'attore Jide Kosoko difende le riforme economiche di Tinubu",
   "orig": "‘Things not as bad as people claim; Tinubu is fixing Nigeria’ — Jide Kosoko",
   "lead": "L'attore veterano nigeriano Jide Kosoko ha affermato che la situazione economica della Nigeria non è così negativa come sostenuto da molti cittadini, difendendo le riforme del presidente Bola Tinubu. Secondo Kosoko, i disagi economici sono reali ma rappresentano un passaggio necessario per correggere decenni di pianificazione inadeguata e spese insostenibili ereditate dai governi precedenti. Le sue dichiarazioni arrivano in un momento di forte malcontento popolare verso le politiche economiche dell'esecutivo, che ha eliminato i sussidi sul carburante e svalutato la moneta nazionale. Lo riferisce Premium Times.",
   "more": [
    "Dal suo arrivo al potere nel 2023, Tinubu ha avviato riforme economiche drastiche, tra cui la fine dei sussidi sul carburante e la liberalizzazione del tasso di cambio, provocando un'impennata dell'inflazione che ha colpito duramente le famiglie nigeriane più povere."
   ],
