   "sez": "salute",
   "titolo": "Ebola nel Nord Kivu: un contagiato su quattro è un bambino sotto i 5 anni",
   "orig": "Msf, in Nord Kivu un caso su quattro di Ebola è un bambino sotto i 5 anni",
   "lead": "Medici Senza Frontiere ha segnalato che nell'epidemia di Ebola in corso nell'est della Repubblica Democratica del Congo, nella provincia del Nord Kivu, un caso su quattro riguarda bambini di età inferiore ai cinque anni. L'organizzazione sottolinea come i più piccoli corrano un rischio di morte superiore rispetto agli adulti e costituiscano una quota rilevante delle persone colpite dal virus. Nel frattempo a Beni è stata avviata la campagna di vaccinazione con il vaccino Ervebo contro la variante Bundibugyo del virus. Lo riferisce Vatican News.",
   "more": [
    "Ebola è una febbre emorragica virale spesso letale, trasmessa tramite contatto con fluidi corporei; le epidemie nella Repubblica Democratica del Congo sono ricorrenti a causa delle difficoltà di accesso sanitario e dei conflitti nelle regioni orientali del paese."
   ],
