   "titolo": "Il Plaza Hotel di New York chiuderà nel 2027 per restauro della facciata",
   "orig": "NYC’s Plaza Hotel to close in 2027 for multiyear facade restoration",
   "lead": "Lo storico Plaza Hotel di New York chiuderà a partire da gennaio 2027 per almeno quattro anni, per sottoporsi a un intervento di restauro della facciata esterna, protetta da vincoli paesaggistici. L'operazione riguarda uno degli edifici più iconici della città, e richiederà un cantiere complesso che va oltre il semplice allestimento di ponteggi, data la delicatezza del lavoro sulla superficie storica dell'immobile. La chiusura prolungata avrà un impatto significativo sull'attività dell'albergo, meta turistica di fama internazionale.",
   "more": [
    "Il Plaza Hotel, inaugurato nel 1907, è uno degli hotel più celebri di New York, situato all'angolo tra la Quinta Strada e Central Park, ed è tutelato come monumento storico cittadino, il che impone procedure di restauro particolarmente rigorose."
   ],
