   "titolo": "Il governo austriaco discute bilancio universitario e 'Zukunftsdepot'",
   "orig": "Regierung berät über Unibudget und „Zukunftsdepot“",
   "lead": "Il governo austriaco, guidato dalla coalizione tra ÖVP, SPÖ e Neos, si è riunito per discutere il finanziamento delle università e un nuovo strumento denominato 'Zukunftsdepot', letteralmente deposito per il futuro. I negoziati, condotti presso la Cancelleria federale, potrebbero portare anche a un accordo sul pacchetto di finanziamento dei media. L'incontro rientra nelle trattative interne alla coalizione di governo su temi economici e sociali rilevanti per il paese. Lo riferisce ORF.",
