   "titolo": "L'Estonia trasforma le case estive sovietiche in patrimonio museale",
   "orig": "Estonia's Soviet-era summer cottage culture to become museum exhibit",
   "lead": "Ricercatori estoni stanno mappando il patrimonio delle casette estive da giardino, chiamate suvila, costruite in tutto il paese durante l'epoca sovietica, con l'obiettivo di preservarne la memoria attraverso un'esposizione museale. Questa cultura abitativa, oggi in via di estinzione, rappresenta una testimonianza significativa della vita quotidiana durante il periodo sovietico in Estonia. Il progetto punta a documentare e valorizzare un fenomeno architettonico e sociale che rischia di scomparire con il passare delle generazioni. Lo riferisce ERR News.",
   "more": [
    "Le suvila sono piccole case da giardino diffuse nell'Estonia sovietica, spesso costruite dagli stessi abitanti nei pressi di orti e appezzamenti coltivati, simbolo di un'epoca di autosufficienza alimentare e tempo libero familiare."
   ],
