   "lead": "La Festa del Cinema di Roma presenta 'Ultimo Fellini', un documentario che raccoglie immagini di repertorio inedite sul celebre regista italiano, scomparso 33 anni fa. Il film raccoglie testimonianze e ricordi di personalità del cinema internazionale, tra cui Roberto Benigni e Martin Scorsese. L'iniziativa si inserisce nelle celebrazioni dedicate alla memoria di uno dei più grandi autori della storia del cinema, in occasione della rassegna romana. Lo riferisce ANSA.",
