   "orig": "‘We’re not playing games’: Parents launch playground protests to fight school field sell-off",
   "lead": "Nella cittadina inglese di Totnes, nel Devon, i residenti si sono organizzati in proteste pacifiche nei fine settimana d'autunno per impedire la vendita di un terreno scolastico aperto, utilizzato per giochi e tempo libero lungo le rive del fiume Dart. La scuola intende cedere l'area per finanziare lavori di ristrutturazione, ma gli abitanti si sono mobilitati con incontri domenicali nel campo, tra giochi con la palla, aquiloni e momenti di socialità, per difendere uno spazio verde considerato prezioso dalla comunità locale.",
