   "titolo": "Stones Throw Records: trent'anni di gusto musicale tra Madvillainy e oltre",
   "orig": "To Madvillainy and beyond: How Stones Throw Records created a galaxy of taste",
   "lead": "L'etichetta discografica di Los Angeles Stones Throw Records celebra trent'anni di attività. Nata come piccola realtà indipendente, ha prodotto classici intergenerazionali come Donuts di J Dilla e lanciato artisti come Sudan Archives e Anderson .Paak. Il racconto ripercorre la storia di un'etichetta che ha segnato la musica indipendente statunitense restando fedele alle proprie radici artistiche, nonostante il successo e la crescita internazionale raggiunti negli anni. Lo riferisce NPR.",
   "more": [
    "Stones Throw Records è nata negli anni Novanta a Los Angeles e si è distinta per un catalogo eclettico, spaziando da hip hop a soul e funk, diventando un punto di riferimento per la musica underground statunitense e internazionale."
   ],
