   "titolo": "NASA analizza lo scudo termico di Artemis II dopo l'ammaraggio",
   "orig": "Artemis II Heat Shield After Splashdown",
   "lead": "Dopo l'ammaraggio della missione Artemis II dello scorso aprile, i sommozzatori della Marina statunitense hanno raccolto immagini subacquee dello scudo termico della capsula Orion. Nei mesi successivi, la NASA ha analizzato i dati per verificare se il sistema di protezione termica avesse efficacemente protetto l'equipaggio e i sistemi del veicolo durante il rientro nell'atmosfera terrestre. L'analisi ha confermato l'efficacia del sistema di protezione. Lo riferisce la NASA.",
   "more": [
    "Artemis II è la missione che ha portato astronauti in orbita lunare senza allunaggio, passo intermedio del programma Artemis che punta a riportare esseri umani sulla Luna. Lo scudo termico è cruciale per proteggere la capsula durante il rientro atmosferico ad alta velocità."
   ],
