   "titolo": "Hong Kong, allarme truffe legate alle prevendite del nuovo iPhone Duo",
   "orig": "Alarms go off as iPhone Duo scams seem to be on cards",
   "lead": "Ad Hong Kong sono stati segnalati casi di presunte truffe legate alle prevendite del nuovo iPhone Duo di Apple, iniziate venerdì notte. Diversi residenti hanno riferito sui social media di essere stati addebitati per molteplici transazioni con carta di credito riferite a un solo ordine, o in alcuni casi senza alcun acquisto effettuato. Alcune transazioni coinvolgevano carte di credito HSBC. La polizia ha ricevuto oltre cento segnalazioni di presunte transazioni non autorizzate, mentre Apple afferma di stare lavorando per identificare e annullare rapidamente le operazioni fraudolente. Lo riferisce RTHK.",
