   "titolo": "Malesia, padre e figlio ritrovati vivi dopo tre giorni nella foresta senza cibo",
   "orig": "Missing father and son found weak after three days in Terengganu forest without food",
   "lead": "A Jerteh, nello stato malese del Terengganu, un padre e un figlio scomparsi giovedì mentre cercavano radici medicinali in una foresta sono stati ritrovati deboli ma vivi dopo tre giorni senza cibo. I soccorritori hanno individuato i due dispersi al termine delle ricerche condotte nell'area boschiva. Le loro condizioni di salute, seppur precarie, non sarebbero gravi dopo l'esperienza vissuta nella fitta vegetazione malese. Lo riferisce Malay Mail.",
