   "sez": "viaggi",
   "titolo": "Griko, l'antico dialetto del Salento che da 3000 anni unisce Puglia e Grecia",
   "orig": "Griko, l’antico dialetto del Salento che da 3000 anni unisce Puglia e Grecia",
   "lead": "Nel Salento, estremo sud della Puglia, sopravvive ancora oggi il griko, un dialetto di origine greca parlato in alcuni paesi della zona. Questo idioma testimonia un legame culturale e linguistico tra la Puglia e la Grecia che dura da circa tre millenni, rendendo il territorio salentino una sorta di propaggine ellenica nel cuore del Mediterraneo meridionale italiano. Lo riferisce Turisti per Caso.",
   "more": [
    "Il griko è parlato in alcuni comuni della Grecìa Salentina, area considerata una delle due isole linguistiche di origine greca ancora presenti in Italia insieme al grecanico calabrese. Le sue origini sono dibattute tra eredità della Magna Grecia e influssi bizantini medievali."
   ],
