   "titolo": "Energia, Palazzo Chigi: recepite le priorità italiane nell'intesa Ue sul decreto bollette",
   "orig": "Energia, P.Chigi: recepite priorità Roma",
   "lead": "Il governo italiano ha annunciato che l'intesa raggiunta con l'Unione Europea sul tema dell'energia ha recepito le priorità indicate da Roma. L'accordo riguarda il decreto bollette, provvedimento legislativo con cui l'Italia intende affrontare il caro energia per famiglie e imprese. Palazzo Chigi ha sottolineato la soddisfazione per il risultato ottenuto nel negoziato con Bruxelles. Lo riferisce Rai News.",
   "more": [
    "Il decreto bollette è uno strumento normativo con cui il governo italiano interviene periodicamente per contenere l'aumento dei costi energetici per cittadini e aziende, spesso tramite sconti in fattura o fondi di compensazione, misure che devono essere coordinate con le regole europee su concorrenza e aiuti di Stato."
   ],
