   "sez": "sport",
   "titolo": "Petra Kvitová torna in campo sette mesi dopo la nascita dei gemelli",
   "orig": "Petra Kvitová returns to tennis courts seven months after giving birth to twins",
   "lead": "La tennista ceca Petra Kvitová, due volte vincitrice di Wimbledon, è tornata a giocare a tennis sette mesi dopo aver partorito due gemelli. Il ritorno in campo segna una nuova fase della carriera dell'atleta, che aveva messo in pausa l'attività agonistica per la maternità. Lo riferisce Radio Prague International.",
   "more": [
    "Petra Kvitová è una delle tenniste più note della storia ceca, vincitrice di Wimbledon nel 2011 e nel 2014. Il suo ritorno alle competizioni dopo la gravidanza si inserisce in una tendenza recente nel tennis femminile, con diverse atlete di alto livello che riprendono l'attività agonistica dopo la maternità."
   ],
