   "id": "zd2d6927b",
   "sez": "mondo",
   "titolo": "Putin promette ritorsioni per gli attacchi ai data center russi, minimizza i danni alle raffinerie",
   "orig": "Putin Vows Retribution for Attacks on Russian Data Centers While Downplaying Damage to Refineries",
   "lead": "Il presidente russo Vladimir Putin ha promesso una risposta agli attacchi che hanno colpito i data center in Russia, minimizzando però i danni subiti dalle raffinerie petrolifere del paese. Il leader russo ha inoltre ammesso che i servizi di sicurezza non avevano previsto gli attacchi contro importanti hub logistici commerciali come Wildberries e Ozon, colossi russi dell'e-commerce. Lo riferisce Moscow Times.",
   "more": [
    "Wildberries e Ozon sono le principali piattaforme di commercio elettronico in Russia, infrastrutture logistiche cruciali per l'economia del paese. Gli attacchi a infrastrutture energetiche e digitali russe si inseriscono nel contesto del conflitto in Ucraina, che negli ultimi anni ha visto colpire sistematicamente raffinerie, data center e reti logistiche."
   ],
