   "titolo": "A 2700 metri tra rocce e ghiaccio: la strada di montagna che segna il confine tra Italia e Francia",
   "orig": "2700 metri di rocce e ghiaccio: il confine tra Italia e Francia passa per una incredibile strada di montagna",
   "lead": "Esiste una strada di montagna che collega Italia e Francia attraversando paesaggi spettacolari a oltre 2700 metri di altitudine, tra rocce e ghiaccio. Il percorso, spesso paragonato a scenari cinematografici, è noto per la sua bellezza ma anche per i tratti impegnativi e in alcuni casi pericolosi che lo caratterizzano, rendendolo una delle strade più suggestive delle Alpi. Lo riferisce Turisti per Caso.",
   "more": [
    "Le Alpi occidentali ospitano numerose strade di alta montagna che collegano Italia e Francia attraverso valichi storici, spesso percorribili solo in determinati periodi dell'anno a causa delle condizioni climatiche estreme in alta quota."
   ],
