   "id": "z41835a7f",
   "sez": "cultura",
   "titolo": "Isabel Allende vince il Premio Planeta da un milione di euro sotto pseudonimo",
   "orig": "Isabel Allende wins €1m Spanish literary prize under pseudonym",
   "lead": "La scrittrice cileno-americana Isabel Allende, 84 anni, ha vinto la 75esima edizione del Premio Planeta, uno dei riconoscimenti letterari più ricchi al mondo con un milione di euro in palio, presentandosi sotto pseudonimo. Il premio è stato assegnato a Allende per il romanzo 'La hora antes del alba', seguito del suo celebre debutto del 1982 'La casa degli spiriti', che torna sui personaggi di quella saga familiare. Lo riferisce The Guardian.",
   "more": [
    "Il Premio Planeta, istituito in Spagna, è uno dei riconoscimenti letterari più remunerativi al mondo e viene tradizionalmente assegnato in forma anonima, con gli autori che presentano le opere sotto pseudonimo fino alla proclamazione del vincitore, prassi che genera spesso sorpresa quando vengono svelate identità già celebri."
   ],
