   "id": "z4ee46c10",
   "sez": "viaggi",
   "titolo": "Polonia, in arrivo una legge per permettere a più comuni di imporre la tassa di soggiorno",
   "orig": "Poland moves to allow more municipalities to charge tourist fee",
   "lead": "Il governo polacco si muove per modificare la legge sulla tassa di soggiorno, estendendo ad altri comuni la possibilità di applicarla ai turisti. La proposta arriva dopo le richieste di Cracovia, città che ha accolto 8,7 milioni di pernottamenti turistici nell'ultimo anno, e che aveva fatto appello per un cambiamento normativo in materia. Lo riferisce Notes from Poland.",
   "more": [
    "La tassa di soggiorno è uno strumento comune in molte città turistiche europee per finanziare servizi legati all'accoglienza dei visitatori. Attualmente in Polonia solo alcune località, spesso balneari o montane, possono applicarla, mentre città d'arte come Cracovia ne erano escluse pur gestendo flussi turistici molto elevati."
   ],
