   "id": "za75061ee",
   "sez": "italia",
   "titolo": "Salvini torna ad attaccare le banche: «Il contributo da 5 miliardi è buonsenso»",
   "orig": "Salvini, nuovo attacco alle banche: “Contributo da 5 miliardi è buonsenso”",
   "lead": "Il vicepremier e leader della Lega Matteo Salvini torna ad attaccare gli istituti di credito, che hanno protestato contro il contributo da 5 miliardi chiesto dal governo. Salvini difende la misura come un intervento «di assoluto buonsenso» e la definisce «il minimo». Respinge anche l'idea che le banche siano state «mazzolate», ricordando i loro maxi utili degli ultimi anni. Giudica poi «sorprendente» la posizione di Antonio Patuelli, presidente dell'Abi, l'associazione delle banche italiane.",
   "more": [
    "L'Abi, Associazione bancaria italiana, rappresenta le banche che operano in Italia e ne porta la voce davanti al governo e alle istituzioni. Il contributo chiesto agli istituti di credito è legato alla manovra di bilancio, che fissa entrate e spese dello Stato per l'anno successivo."
   ],
