   "id": "z3025a501",
   "sez": "organizzazioni",
   "titolo": "Il Fmi chiede sostegno per i Paesi poveri colpiti da inflazione e guerre",
   "orig": "IMF urges support for poorer nations facing high inflation, war spillovers",
   "lead": "Il Fondo monetario internazionale chiede alla comunità internazionale di sostenere i Paesi più poveri. Queste economie devono fare i conti con un'inflazione elevata e con le ricadute dei conflitti in corso. La direttrice del Fmi ha spiegato che le nazioni a basso reddito arrivano a destinare fino al 14 per cento delle loro entrate al rimborso dei debiti. Sono risorse sottratte ad altre spese pubbliche, proprio mentre la pressione economica cresce. Lo riferisce Al Jazeera.",
   "more": [
    "Il Fondo monetario internazionale è un'istituzione che riunisce quasi tutti i Paesi del mondo. Sorveglia la stabilità economica globale e concede prestiti agli Stati in difficoltà finanziaria. Quando una quota ampia delle entrate serve a pagare i debiti, resta meno spazio per servizi come sanità e istruzione."
   ],
