   "id": "zc22645e8",
   "sez": "cultura",
   "titolo": "The Celebrity Traitors: le lacrime e i balli di Miranda Hart rubano la scena",
   "orig": "Miranda's tears, joy and dance moves steal show as deadly boredom sets in on The Celebrity Traitors",
   "lead": "Nella puntata di venerdì del reality britannico The Celebrity Traitors, l'attrice Miranda Hart si è commossa e ha parlato dei suoi problemi di salute. Con le sue lacrime, la sua gioia e i suoi passi di danza è diventata la protagonista, in un episodio giudicato in parte noioso. La quarta puntata aveva visto altri due concorrenti lasciare il gioco, una missione macabra vicino a un cimitero e un colpo di scena da brivido. Il giornalista Amol Rajan, uscito presto dal programma, debutta intanto su YouTube.",
   "more": [
    "The Traitors è un gioco televisivo in cui alcuni concorrenti, i «traditori», devono eliminare gli altri senza farsi scoprire, mentre i «fedeli» cercano di smascherarli. La versione con personaggi famosi va in onda sulla BBC. Miranda Hart è un'attrice comica britannica molto popolare."
   ],
