   "id": "zaa828f65",
   "sez": "salute",
   "titolo": "Delhi, i familiari dei malati dormono sui marciapiedi fuori dagli ospedali",
   "orig": "Sidewalk sleepers: They have nowhere else to stay while a loved one is in the hospital",
   "lead": "A Delhi molti pazienti percorrono lunghe distanze per farsi curare negli ospedali pubblici. Chi ne ha bisogno riceve aiuti economici per pagare le cure. Per dormire, però, le famiglie che li accompagnano sono spesso lasciate a sé stesse. Molti parenti passano così la notte per strada, sui marciapiedi intorno agli ospedali, perché non hanno nessun altro posto dove restare mentre una persona cara è ricoverata. Lo riferisce NPR.",
   "more": [
    "Delhi, capitale dell'India, ospita alcuni dei più grandi ospedali pubblici del Paese. Vi arrivano malati da molte regioni, spesso in cerca di cure specialistiche che altrove non trovano. In India è comune che i familiari accompagnino e assistano i pazienti per tutto il ricovero."
   ],
