   "sez": "cultura",
   "titolo": "Robyn Williams lascia The Science Show dell'Abc dopo 51 anni",
   "orig": "Long-serving ABC broadcaster Robyn Williams to leave The Science Show after 51 years",
   "lead": "Il conduttore australiano Robyn Williams, 82 anni, lascia The Science Show dell'Abc dopo averlo condotto per 51 anni. La televisione e radio pubblica australiana vuole rinnovare la sua programmazione scientifica, ma non ha ancora indicato chi lo sostituirà. L'annuncio ai media parla soltanto della «prossima generazione». L'addio arriva due settimane dopo quello del giornalista economico Alan Kohler, che ha annunciato il ritiro dopo trent'anni. Lo riferisce The Guardian.",
   "more": [
    "L'Abc, Australian Broadcasting Corporation, è il servizio pubblico radiotelevisivo dell'Australia. The Science Show è un programma radiofonico dedicato alla divulgazione scientifica, con interviste a ricercatori e approfondimenti sulle scoperte."
   ],
