   "id": "z11ff7835",
   "sez": "salute",
   "titolo": "Perché Elizabeth Holmes continua ad affascinarci",
   "orig": "‘You can’t make this stuff up’: why we remain fascinated by Elizabeth Holmes",
   "lead": "Un nuovo documentario su Elizabeth Holmes, l'imprenditrice poi condannata per frode, è dato tra i favoriti agli Oscar. Il film offre uno sguardo insolito sulla sua strana eredità. L'oncologo David Agus ricorda il primo incontro con lei a una conferenza sulla salute. Dietro le quinte era cordiale e simpatica, sul palco gli sembrò un'altra persona, con un accento diverso e una voce profonda e molto seria. Lo riferisce The Guardian.",
   "more": [
    "Elizabeth Holmes ha fondato Theranos, una società della Silicon Valley che prometteva di eseguire molti esami del sangue con poche gocce. La tecnologia non funzionava come dichiarato. Il caso è diventato uno dei più noti scandali del settore e lei è stata condannata per frode."
   ],
