   "id": "z9f0bf539",
   "sez": "cultura",
   "titolo": "The Audacity, la satira tagliente sui padroni della Silicon Valley",
   "orig": "The Audacity: this witty tech-bro takedown from a Succession writer is packed with glorious one-liners",
   "lead": "Arriva su HBO Max The Audacity, una serie creata da Jonathan Glatzer, già autore di Succession. È una satira nerissima ambientata nella Silicon Valley, che mette a nudo l'avidità dei grandi capi delle aziende tecnologiche e l'ego dei miliardari. La critica la descrive ricca di battute brillanti e con un ritmo misurato e intrigante, simile a quello di Better Call Saul. Secondo la recensione, la serie mostra quanto del presente sia stato plasmato da pochi uomini. Lo riferisce The Guardian.",
   "more": [
    "La Silicon Valley è l'area della California dove hanno sede molte delle più grandi aziende tecnologiche del mondo. Succession è una serie di grande successo sulle lotte di potere in una famiglia di magnati dei media, mentre Better Call Saul è nota per il ritmo lento e curato."
   ],
