   "id": "z9888b39b",
   "sez": "cultura",
   "titolo": "«Aura», l'archivio di Valentino tra bellezze nascoste e rivelate",
   "orig": "Aura, l'archivio Valentino tra bellezze nascoste e rivelate",
   "lead": "La Fondazione Garavani Giammetti presenta «Aura», un progetto espositivo dedicato all'archivio di Valentino. Il pubblico potrà vedere 38 capi della maison, tra bellezze rimaste a lungo nascoste e altre finalmente svelate. Gli abiti dialogano con le opere dell'artista Juszkiewicz, in un incontro tra moda e arte contemporanea. L'iniziativa offre uno sguardo sul patrimonio creativo della casa di moda. Lo riferisce ANSA.",
   "more": [
    "Valentino Garavani è uno degli stilisti italiani più celebri, noto per l'alta moda e per il suo caratteristico rosso. Con il socio Giancarlo Giammetti ha fondato la maison e poi una fondazione che custodisce e valorizza il suo archivio."
   ],
