   "sez": "economia",
   "titolo": "Carburanti ancora cari: il gasolio in autostrada sfiora i 2,3 euro al litro",
   "orig": "Carburanti, prezzi ancora sotto pressione: il gasolio sfiora i 2,3 euro al litro in autostrada",
   "lead": "I prezzi dei carburanti restano sotto pressione in Italia. Sulla rete autostradale il prezzo medio del gasolio in modalità self service sfiora ormai i 2,3 euro al litro. Il dato arriva dall'ultima rilevazione diffusa dal Mimit, il ministero delle Imprese e del made in Italy, che raccoglie i listini comunicati dai distributori. Per chi viaggia in autostrada il pieno resta quindi particolarmente costoso. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "Il Mimit è il ministero delle Imprese e del made in Italy, che pubblica regolarmente i prezzi medi dei carburanti comunicati dai distributori. In autostrada i prezzi sono di solito più alti che sulla rete ordinaria. Il self service costa in genere meno del servizio con addetto."
   ],
